      .sutol-edeb-14-left { transform-origin: left center; animation: sutol-edeb-14-openL 5s ease-in-out infinite; }
      .sutol-edeb-14-right { transform-origin: right center; animation: sutol-edeb-14-openR 5s ease-in-out infinite; }
      @keyframes sutol-edeb-14-openL {
        0%, 15% { transform: scaleX(1); }
        45%, 80% { transform: scaleX(0.12); }
        100% { transform: scaleX(1); }
