  PresentationComponentDefinition(
    kind: PresentationComponentKind.edebiyat34,
    id: "edebiyat-34-kalem-ucundan-dokulen-sekil-yagmuru",
    label: "Kalem Ucundan Dökülen Şekil Yağmuru",
    category: "Edebiyat",
    tags: <String>["dil", "üslup", "şiir dizesi", "edebiyat"],
    description:
        "Sabit bir kalem ucundan aşağı doğru sürekli dökülen küçük soyut işaretlerin, yazının akışını simgeleyen bir yağmur gibi düşmesi.",
    html: r'''<div class="sutol-edeb34-wrap">
  <canvas class="sutol-edeb34-canvas"></canvas>
</div>
<style>
.sutol-edeb34-wrap{width:100%;height:100%;background:transparent;}
.sutol-edeb34-canvas{width:100%;height:100%;display:block;}
</style>
<script>
(function(){
  var container = document.currentScript.closest('.sutol-edeb34-wrap');
  var canvas = container.querySelector('.sutol-edeb34-canvas');
  var ctx = canvas.getContext('2d');
  var reduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var marks = [];
  var n = 12;
  function resize(){
    canvas.width = canvas.clientWidth || 300;
    canvas.height = canvas.clientHeight || 150;
  }
  function init(){
    resize();
    marks = [];
    for(var i=0;i<n;i++){
      marks.push({
        x: canvas.width*0.5 + (Math.random()-0.5)*canvas.width*0.5,
        y: Math.random()*canvas.height,
        speed: (reduced?0.3:1) * (0.6 + Math.random()*0.8),
        w: 3 + Math.random()*4,
        h: 8 + Math.random()*8,
        rot: Math.random()*Math.PI
      });
    }
  }
  function draw(){
    ctx.clearRect(0,0,canvas.width,canvas.height);
    for(var i=0;i<marks.length;i++){
      var m = marks[i];
      m.y += m.speed;
      if(m.y > canvas.height){ m.y = -10; m.x = canvas.width*0.5 + (Math.random()-0.5)*canvas.width*0.5; }
      ctx.save();
      ctx.translate(m.x, m.y);
      ctx.rotate(m.rot);
      ctx.fillStyle = 'rgba(58,42,32,0.55)';
      ctx.fillRect(-m.w/2, -m.h/2, m.w, m.h);
      ctx.restore();
    }
    requestAnimationFrame(draw);
  }
  init();
  window.addEventListener('resize', resize);
  requestAnimationFrame(draw);
})();
</script>''',
