  PresentationComponentDefinition(
    kind: PresentationComponentKind.egitim07,
    id: "egitim-07-kaynayan-deney-tupu",
    label: "Kaynayan Deney Tüpü",
    category: "Eğitim",
    tags: <String>["bilim insanı", "araştırma", "makale", "tez"],
    description:
        "İçinde renkli sıvının kaynayıp kabarcıklar yükselttiği bir deney tüpü; kabarcıklar canvas ile çizilir.",
    html: r'''<div class="sutol-edu07-wrap">
  <style>
    .sutol-edu07-wrap{position:relative;width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;}
    .sutol-edu07-stage{position:relative;width:60%;max-width:180px;aspect-ratio:1/2;}
    .sutol-edu07-tube{position:absolute;inset:0;width:100%;height:100%;}
    .sutol-edu07-canvas{position:absolute;left:18%;right:18%;top:38%;bottom:8%;width:64%;height:54%;}
  </style>
  <div class="sutol-edu07-wrap">
    <div class="sutol-edu07-stage">
      <svg class="sutol-edu07-tube" viewBox="0 0 100 200">
        <path d="M35,10 L35,120 Q35,170 65,170 Q95,170 95,120 L95,10" fill="none" stroke="#cfd8e3" stroke-width="4"/>
        <path d="M37,120 Q37,168 65,168 Q93,168 93,120 Z" fill="#57c48b" opacity="0.55"/>
        <line x1="25" y1="10" x2="105" y2="10" stroke="#cfd8e3" stroke-width="4" stroke-linecap="round"/>
      </svg>
      <canvas class="sutol-edu07-canvas" width="120" height="110"></canvas>
    </div>
  </div>
  <script>
    (function(){
      var root = document.currentScript.closest('.sutol-edu07-wrap');
      var canvas = root.querySelector('.sutol-edu07-canvas');
      var ctx = canvas.getContext('2d');
      var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      var bubbles = [];
      function spawn(){
        bubbles.push({x: 15 + Math.random()*70, y: 100, r: 2+Math.random()*3, v: 0.3+Math.random()*0.5});
      }
      var last = 0;
      function frame(ts){
        if(!last) last = ts;
        var dt = ts - last; last = ts;
        if(!reduce && Math.random() < 0.06) spawn();
        ctx.clearRect(0,0,canvas.width,canvas.height);
        for(var i=bubbles.length-1;i>=0;i--){
          var b = bubbles[i];
          if(!reduce) b.y -= b.v * (dt/16);
          ctx.beginPath();
          ctx.fillStyle = 'rgba(255,255,255,0.55)';
          ctx.arc(b.x, b.y, b.r, 0, Math.PI*2);
          ctx.fill();
          if(b.y < 5) bubbles.splice(i,1);
        }
        requestAnimationFrame(frame);
      }
      requestAnimationFrame(frame);
    })();
  </script>
</div>''',
  ),
