    tags: <String>["sınav", "ödev", "disiplin", "değerlendirme"],
    description:
        "İçinde canvas ile çizilen kum tanelerinin sürekli aşağı süzüldüğü bir kum saati.",
    html: r'''<div class="sutol-edu19-wrap">
  <style>
    .sutol-edu19-wrap{position:relative;width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;}
    .sutol-edu19-stage{position:relative;width:55%;max-width:170px;aspect-ratio:3/5;}
    .sutol-edu19-glass{position:absolute;inset:0;width:100%;height:100%;}
    .sutol-edu19-canvas{position:absolute;left:6%;right:6%;top:4%;bottom:4%;width:88%;height:92%;}
  </style>
  <div class="sutol-edu19-wrap">
    <div class="sutol-edu19-stage">
      <svg class="sutol-edu19-glass" viewBox="0 0 120 200">
        <path d="M15,10 H105 V30 L65,100 L105,170 V190 H15 V170 L55,100 L15,30 Z" fill="none" stroke="#c9b28a" stroke-width="4" stroke-linejoin="round"/>
        <rect x="10" y="4" width="100" height="10" rx="3" fill="#8a5a34"/>
        <rect x="10" y="186" width="100" height="10" rx="3" fill="#8a5a34"/>
      </svg>
      <canvas class="sutol-edu19-canvas" width="120" height="184"></canvas>
    </div>
  </div>
  <script>
    (function(){
      var root = document.currentScript.closest('.sutol-edu19-wrap');
      var canvas = root.querySelector('.sutol-edu19-canvas');
      var ctx = canvas.getContext('2d');
      var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      var grains = [];
      var W = canvas.width, H = canvas.height;
      function spawn(){
        grains.push({x: W/2 + (Math.random()*6-3), y: 22, v: 1.2+Math.random()*0.8, settled:false, sx: W/2 + (Math.random()*30-15)});
      }
      var last = 0, cycle = 0;
      function frame(ts){
        if(!last) last = ts;
        var dt = ts - last; last = ts;
        cycle += dt;
        if(cycle > 5000){ grains = []; cycle = 0; }
        if(!reduce && Math.random() < 0.25 && grains.length < 90) spawn();
        ctx.clearRect(0,0,W,H);
        ctx.fillStyle = '#e8c987';
        for(var i=0;i<grains.length;i++){
          var g = grains[i];
          if(!reduce && !g.settled){
            g.y += g.v * (dt/16);
            if(g.y > H-18){ g.y = H-18; g.settled = true; }
          }
          ctx.beginPath();
          ctx.arc(g.x, g.y, 1.6, 0, Math.PI*2);
          ctx.fill();
        }
        requestAnimationFrame(frame);
      }
      requestAnimationFrame(frame);
    })();
  </script>
</div>''',
  ),
