  PresentationComponentDefinition(
    kind: PresentationComponentKind.cografya21,
    id: "cografya-21-deprem-sismograf",
    label: "Deprem Sismografı",
    category: "Coğrafya",
    tags: <String>["deprem", "sismograf", "yerkabuğu", "hareket"],
    description:
        "Canlı bir sismografın kağıt üzerinde çizdiği deprem dalgalanmalarını gösteren bir görüntü.",
    html: r'''<div class="sutol-geo21-wrap">
  <canvas class="sutol-geo21-canvas"></canvas>
  <style>
  .sutol-geo21-wrap{position:relative;width:100%;height:100%;background:transparent;overflow:hidden;}
  .sutol-geo21-canvas{width:100%;height:100%;display:block;}
  @media (prefers-reduced-motion: reduce){
    .sutol-geo21-wrap{ }
  }
  </style>
  <script>
  (function(){
    var script = document.currentScript;
    var wrap = script.closest('.sutol-geo21-wrap');
    var canvas = wrap.querySelector('.sutol-geo21-canvas');
    var ctx = canvas.getContext('2d');
    var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    var t = 0;
    function resize(){
      var rect = wrap.getBoundingClientRect();
      canvas.width = rect.width;
      canvas.height = rect.height;
    }
    resize();
    window.addEventListener('resize', resize);
    function draw(){
      var w = canvas.width, h = canvas.height;
      ctx.clearRect(0,0,w,h);
      ctx.strokeStyle = '#E63946';
      ctx.lineWidth = 2;
      ctx.beginPath();
      var mid = h/2;
      var step = reduce ? (2/3) : 2;
      t += step;
      var n = Math.floor(w);
      for(var x=0;x<n;x++){
        var phase = (x - t);
        var spike = Math.sin(phase*0.05) * 6 + Math.sin(phase*0.13) * 10 * Math.exp(-Math.pow(((phase%240)-40)/20,2));
        var y = mid + spike;
        if(x===0){ ctx.moveTo(x,y); } else { ctx.lineTo(x,y); }
      }
      ctx.stroke();
      requestAnimationFrame(draw);
    }
    requestAnimationFrame(draw);
  })();
  </script>
</div>''',
  ),
