  PresentationComponentDefinition(
    kind: PresentationComponentKind.muzik17,
    id: "muzik-17-caz-saksafon-tutunu",
    label: "Caz Saksafon Tütünü",
    category: "Müzik",
    tags: <String>["caz", "enstrüman", "sanatçı", "performans"],
    description:
        "Bir saksafon ağzından yükselen, dağılıp kaybolan sisli parçacıklar (tuval tabanlı animasyon).",
    html: r'''<div class="sutol-muz17-root">
  <canvas class="sutol-muz17-canvas"></canvas>
</div>
<style>
  .sutol-muz17-root{width:100%;height:100%;background:transparent;position:relative;overflow:hidden;}
  .sutol-muz17-canvas{width:100%;height:100%;display:block;}
</style>
<script>
(function(){
  var root = document.currentScript.previousElementSibling;
  var canvas = root.querySelector('.sutol-muz17-canvas');
  var ctx = canvas.getContext('2d');
  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var particles = [];
  var w = 0, h = 0;

  function resize(){
    var rect = root.getBoundingClientRect();
    w = Math.max(1, rect.width);
    h = Math.max(1, rect.height);
    canvas.width = w;
    canvas.height = h;
  }
  resize();
  window.addEventListener('resize', resize);

  function spawn(){
    particles.push({
      x: w * 0.28 + (Math.random()-0.5) * w * 0.05,
      y: h * 0.55,
      r: 4 + Math.random() * 5,
      vy: -(0.25 + Math.random() * 0.35) * (reduceMotion ? 0.3 : 1),
      vx: (Math.random()-0.5) * 0.3,
      life: 0,
      maxLife: 180 + Math.random() * 80
    });
  }

  var frame = 0;
  function loop(){
    frame++;
    ctx.clearRect(0,0,w,h);

    if (frame % (reduceMotion ? 14 : 5) === 0 && particles.length < 40){
      spawn();
    }

    for (var i = particles.length - 1; i >= 0; i--){
      var p = particles[i];
      p.life++;
      p.x += p.vx;
      p.y += p.vy;
      p.r += 0.03;
      var t = p.life / p.maxLife;
      var alpha = Math.max(0, 0.55 * (1 - t));
      if (t >= 1){
        particles.splice(i,1);
        continue;
      }
      ctx.beginPath();
      ctx.fillStyle = 'rgba(200,190,220,' + alpha.toFixed(3) + ')';
      ctx.arc(p.x, p.y, p.r, 0, Math.PI*2);
      ctx.fill();
    }

    ctx.fillStyle = '#C08A3E';
    ctx.beginPath();
    ctx.moveTo(w*0.15, h*0.7);
    ctx.quadraticCurveTo(w*0.15, h*0.45, w*0.28, h*0.5);
    ctx.quadraticCurveTo(w*0.4, h*0.55, w*0.32, h*0.75);
    ctx.quadraticCurveTo(w*0.28, h*0.9, w*0.15, h*0.7);
    ctx.fill();

    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
</script>''',
  ),
