  PresentationComponentDefinition(
    kind: PresentationComponentKind.muzik36,
    id: "muzik-36-osiloskop-dalga-formu-taramas",
    label: "Osiloskop Dalga Formu Taraması",
    category: "Müzik",
    tags: <String>["ses dalgası", "frekans", "kayıt", "akustik"],
    description:
        "Bir osiloskop ekranında sürekli akan sinüs dalga formunu canvas üzerinde çizerek canlandırır.",
    html: r'''<div class="sutol-muz36-wrap">
<style>
.sutol-muz36-wrap{position:relative;width:100%;height:100%;background:transparent;}
.sutol-muz36-canvas{width:100%;height:100%;display:block;}
</style>
<canvas class="sutol-muz36-canvas"></canvas>
<script>
(function(){
var container = document.currentScript.parentElement;
var canvas = container.querySelector('.sutol-muz36-canvas');
var ctx = canvas.getContext('2d');
var reduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var t = 0;
function resize(){
canvas.width = container.clientWidth;
canvas.height = container.clientHeight;
}
resize();
window.addEventListener('resize', resize);
function draw(){
var w = canvas.width, h = canvas.height;
ctx.clearRect(0,0,w,h);
ctx.strokeStyle = '#39ff88';
ctx.lineWidth = Math.max(1, h*0.01);
ctx.beginPath();
for(var x=0;x<=w;x+=2){
var y = h/2 + Math.sin((x*0.04) + t) * (h*0.28) * Math.exp(-Math.pow((x/w-0.5)*2,2));
if(x===0){ ctx.moveTo(x,y); } else { ctx.lineTo(x,y); }
}
ctx.stroke();
t += reduced ? 0.01 : 0.06;
requestAnimationFrame(draw);
}
draw();
})();
</script>
</div>''',
  ),
