  PresentationComponentDefinition(
    kind: PresentationComponentKind.felsefeDin15,
    id: "felsefe-din-15-kozmogoni-patlamas",
    label: "Kozmogoni Patlaması",
    category: "Felsefe / Din",
    tags: <String>["kozmogoni", "varlıklar", "gerçeklik"],
    description:
        "Merkezi bir noktadan dışarı doğru genişleyen parçacıklarla evrenin doğuşunu betimleyen canvas animasyonu.",
    html: r'''<div class="sutol-fd-15-root">
  <style>
    .sutol-fd-15-root{position:relative;width:100%;height:100%;overflow:hidden;background:transparent;}
    .sutol-fd-15-root canvas{width:100%;height:100%;display:block;}
  </style>
  <canvas class="sutol-fd-15-canvas"></canvas>
  <script>
    (function(){
      var root = document.currentScript.closest('.sutol-fd-15-root');
      var canvas = root.querySelector('.sutol-fd-15-canvas');
      var ctx = canvas.getContext('2d');
      var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      var particles = [];
      var W, H;
      function resize(){
        W = canvas.clientWidth; H = canvas.clientHeight;
        canvas.width = W * devicePixelRatio; canvas.height = H * devicePixelRatio;
        ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);
      }
      function spawn(){
        var angle = Math.random()*Math.PI*2;
        var speed = 0.4 + Math.random()*0.9;
        var colors = ['#f2b134','#f26430','#c94277','#6a4c93','#5fa8d3'];
        particles.push({
          x:0,y:0,angle:angle,speed:speed,
          life:0, maxLife: 90 + Math.random()*60,
          color: colors[Math.floor(Math.random()*colors.length)]
        });
      }
      var ro = new ResizeObserver(resize);
      ro.observe(canvas);
      resize();
      var frame = 0;
      function tick(){
        frame++;
        if(frame % 4 === 0 && particles.length < 140) spawn();
        ctx.clearRect(0,0,W,H);
        var cx = W/2, cy = H/2;
        for(var i=particles.length-1;i>=0;i--){
          var p = particles[i];
          p.life++;
          var t = p.life / p.maxLife;
          if(t >= 1){ particles.splice(i,1); continue; }
          var dist = p.speed * p.life * (Math.min(W,H)/220);
          var x = cx + Math.cos(p.angle)*dist;
          var y = cy + Math.sin(p.angle)*dist;
          ctx.globalAlpha = 1 - t;
          ctx.fillStyle = p.color;
          ctx.beginPath();
          ctx.arc(x,y,2.2,0,Math.PI*2);
          ctx.fill();
        }
        ctx.globalAlpha = 0.9;
        ctx.fillStyle = '#fff6d5';
        ctx.beginPath();
        ctx.arc(cx,cy,4,0,Math.PI*2);
        ctx.fill();
        ctx.globalAlpha = 1;
        if(!reduced) requestAnimationFrame(tick);
      }
      if(reduced){
        for(var i=0;i<40;i++) spawn();
        tick();
      } else {
        requestAnimationFrame(tick);
      }
    })();
  </script>
</div>''',
  ),
