  PresentationComponentDefinition(
    kind: PresentationComponentKind.sanat06,
    id: "sanat-06-empresyonist-is-k-noktac-l-k",
    label: "Empresyonist Işık (Noktacılık)",
    category: "Sanat",
    tags: <String>["empresyonizm", "akım", "üslup", "ışık gölge"],
    description:
        "Binlerce küçük renkli noktanın titreşerek bir ışık izlenimi oluşturduğu tuval (canvas tabanlı).",
    html: r'''<div class="sutol-art-06-root">
  <canvas class="sutol-art-06-canvas"></canvas>
</div>
<style>
  .sutol-art-06-root{width:100%;height:100%;position:relative;background:transparent;}
  .sutol-art-06-canvas{width:100%;height:100%;display:block;}
</style>
<script>
(function(){
  var root = document.currentScript.parentElement.querySelector('.sutol-art-06-root');
  var canvas = root.querySelector('.sutol-art-06-canvas');
  var ctx = canvas.getContext('2d');
  var palette = ['#F4A261','#E76F51','#2A9D8F','#E9C46A','#264653'];
  var dots = [];
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function resize(){
    var rect = root.getBoundingClientRect();
    canvas.width = Math.max(1, rect.width);
    canvas.height = Math.max(1, rect.height);
    buildDots();
  }
  function buildDots(){
    dots = [];
    var count = 160;
    for(var i=0;i<count;i++){
      dots.push({
        x: Math.random()*canvas.width,
        y: Math.random()*canvas.height,
        r: 2 + Math.random()*4,
        c: palette[Math.floor(Math.random()*palette.length)],
        phase: Math.random()*Math.PI*2,
        speed: 0.6 + Math.random()*0.8
      });
    }
  }
  var start = null;
  function frame(ts){
    if(start===null) start = ts;
    var t = (ts-start)/1000;
    ctx.clearRect(0,0,canvas.width,canvas.height);
    for(var i=0;i<dots.length;i++){
      var d = dots[i];
      var a = 0.45 + 0.45*Math.sin(t*d.speed + d.phase);
      ctx.globalAlpha = a;
      ctx.fillStyle = d.c;
      ctx.beginPath();
      ctx.arc(d.x, d.y, d.r, 0, Math.PI*2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
    if(!reduced) requestAnimationFrame(frame);
  }
  window.addEventListener('resize', resize);
  resize();
  if(reduced){
    dots.forEach(function(d){ });
    requestAnimationFrame(function(){ frame(0); });
  } else {
    requestAnimationFrame(frame);
  }
})();
</script>''',
