    html: r'''<div class="sutol-art-11-root">
  <svg class="sutol-art-11-svg" viewBox="0 0 400 400" preserveAspectRatio="xMidYMid meet">
    <g class="sutol-art-11-grid"></g>
  </svg>
</div>
<style>
  .sutol-art-11-root{width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;}
  .sutol-art-11-svg{width:100%;height:100%;}
  .sutol-art-11-tile{ animation: sutol-art-11-fade 4s ease-in-out infinite; transform-box: fill-box; transform-origin:center; }
  @keyframes sutol-art-11-fade{
    0%,100%{ opacity:0.25; transform:scale(0.85); }
    50%{ opacity:1; transform:scale(1); }
  }
  @media (prefers-reduced-motion: reduce){
    .sutol-art-11-tile{ animation:none; opacity:0.9; transform:scale(1); }
  }
</style>
<script>
(function(){
  var container = document.currentScript.parentElement;
  var svg = container.querySelector('.sutol-art-11-svg');
  var g = svg.querySelector('.sutol-art-11-grid');
  var palette = ['#264653','#2A9D8F','#E9C46A','#F4A261','#E76F51'];
  var size = 40, cols = 10, rows = 10;
  var ns = 'http://www.w3.org/2000/svg';
  var i = 0;
  for(var r=0;r<rows;r++){
    for(var c=0;c<cols;c++){
      var rect = document.createElementNS(ns,'rect');
      rect.setAttribute('x', c*size+2);
      rect.setAttribute('y', r*size+2);
      rect.setAttribute('width', size-4);
      rect.setAttribute('height', size-4);
      rect.setAttribute('rx', 3);
      rect.setAttribute('fill', palette[(r+c)%palette.length]);
      rect.setAttribute('class','sutol-art-11-tile');
      rect.style.animationDelay = ((r+c)*0.08)+'s';
      g.appendChild(rect);
      i++;
    }
  }
})();
</script>''',
