    html: r'''<div id="sutol-tar-01" class="sutol-tar-01-root">
<style>
.sutol-tar-01-root{width:100%;height:100%;position:relative;background:transparent;}
.sutol-tar-01-canvas{width:100%;height:100%;display:block;position:relative;z-index:1;}
.sutol-tar-01-frame{position:absolute;inset:0;display:block;z-index:2;pointer-events:none;}
.sutol-tar-01-topSand{animation:sutol-tar-01-drain 6s linear infinite;transform-origin:200px 140px;}
.sutol-tar-01-botSand{animation:sutol-tar-01-fill 6s linear infinite;transform-origin:200px 260px;}
@keyframes sutol-tar-01-drain{0%{transform:scaleY(1);}95%{transform:scaleY(0.02);}100%{transform:scaleY(1);}}
@keyframes sutol-tar-01-fill{0%{transform:scaleY(0.02);}95%{transform:scaleY(1);}100%{transform:scaleY(0.02);}}
@media (prefers-reduced-motion: reduce){
  .sutol-tar-01-topSand,.sutol-tar-01-botSand{animation-duration:24s;}
}
</style>
<svg class="sutol-tar-01-frame" viewBox="0 0 400 400" preserveAspectRatio="xMidYMid meet">
  <defs>
    <linearGradient id="sutol-tar-01-wood" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="#c9924f"/><stop offset="100%" stop-color="#8a5a2b"/>
    </linearGradient>
  </defs>
  <rect x="140" y="90" width="120" height="12" rx="4" fill="url(#sutol-tar-01-wood)"/>
  <rect x="140" y="298" width="120" height="12" rx="4" fill="url(#sutol-tar-01-wood)"/>
  <path d="M152 102 L248 102 L206 198 L206 202 L248 298 L152 298 L194 202 L194 198 Z" fill="none" stroke="#c9b28a" stroke-width="3" opacity=".7"/>
  <clipPath id="sutol-tar-01-topClip"><path d="M155 105 L245 105 L200 198 L200 198 Z"/></clipPath>
  <clipPath id="sutol-tar-01-botClip"><path d="M200 202 L200 202 L245 295 L155 295 Z"/></clipPath>
  <g clip-path="url(#sutol-tar-01-topClip)">
    <rect class="sutol-tar-01-topSand" x="150" y="105" width="100" height="93" fill="#e8c27a"/>
  </g>
  <g clip-path="url(#sutol-tar-01-botClip)">
    <rect class="sutol-tar-01-botSand" x="150" y="202" width="100" height="93" fill="#e8c27a"/>
  </g>
</svg>
<canvas class="sutol-tar-01-canvas"></canvas>
<script>
(function(){
  var root = document.getElementById('sutol-tar-01');
  var canvas = root.querySelector('.sutol-tar-01-canvas');
  var ctx = canvas.getContext('2d');
  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  function resize(){
    var r = root.getBoundingClientRect();
    canvas.width = Math.max(1, r.width);
    canvas.height = Math.max(1, r.height);
  }
  if (window.ResizeObserver){ new ResizeObserver(resize).observe(root); }
  resize();
  var scaleX = function(){ return canvas.width/400; };
  var scaleY = function(){ return canvas.height/400; };
  var t = 0;
  var cycle = reduce ? 24000 : 6000;
  function draw(){
    ctx.clearRect(0,0,canvas.width,canvas.height);
    var sx = scaleX(), sy = scaleY();
    var phase = (t % cycle) / cycle;
    if (phase < 0.95){
      var cx = 200*sx, cy = 200*sy;
      for (var i=0;i<3;i++){
        var off = (phase*40 + i*7) % 12;
        ctx.beginPath();
        ctx.arc(cx + (Math.sin(t*0.01+i)*2*sx), cy + off*sy, 1.6*sx, 0, Math.PI*2);
        ctx.fillStyle = '#f0d18a';
        ctx.fill();
      }
    }
    t += 16;
    requestAnimationFrame(draw);
  }
  requestAnimationFrame(draw);
})();
</script>
</div>''',
