</style>
<svg class="sutol-tar-11-svg" viewBox="0 0 400 400" preserveAspectRatio="xMidYMid meet">
  <rect x="180" y="90" width="8" height="240" fill="#5a4128"/>
  <g class="sutol-tar-11-band1"><rect x="188" y="100" width="120" height="24" fill="#c1272d"/></g>
  <g class="sutol-tar-11-band2"><rect x="188" y="124" width="120" height="24" fill="#efefef"/></g>
  <g class="sutol-tar-11-band1"><rect x="188" y="148" width="120" height="24" fill="#c1272d"/></g>
</svg>
<canvas class="sutol-tar-11-canvas"></canvas>
<script>
(function(){
  var root = document.getElementById('sutol-tar-11');
  var canvas = root.querySelector('.sutol-tar-11-canvas');
  var ctx = canvas.getContext('2d');
  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var particles = [];
  function resize(){
    var r = root.getBoundingClientRect();
    canvas.width = Math.max(1, r.width);
    canvas.height = Math.max(1, r.height);
  }
  if (window.ResizeObserver){ new ResizeObserver(resize).observe(root); }
  resize();
  function spawn(){
    var sx = canvas.width/400;
    particles.push({x:190*sx + Math.random()*10*sx, y:canvas.height*0.82, r:1.2+Math.random()*1.6, vy:0.3+Math.random()*0.5, life:0, max:80+Math.random()*40});
  }
  var timer=0;
  function draw(){
    ctx.clearRect(0,0,canvas.width,canvas.height);
    timer++;
    if (timer > (reduce?60:20)){ spawn(); timer=0; }
    for (var i=particles.length-1;i>=0;i--){
      var p = particles[i];
      p.y -= p.vy; p.life++;
      ctx.globalAlpha = Math.max(0, 1 - p.life/p.max);
      ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,Math.PI*2); ctx.fillStyle='#e0b268'; ctx.fill();
      if (p.life > p.max) particles.splice(i,1);
    }
    ctx.globalAlpha = 1;
    requestAnimationFrame(draw);
  }
  requestAnimationFrame(draw);
})();
</script>
</div>''',
