      p.y -= 0.6; p.x += 0.15; p.r += 0.35; p.life++;
      ctx.globalAlpha = Math.max(0, 0.5 - p.life/p.max*0.5);
      ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,Math.PI*2); ctx.fillStyle='#cfd3d8'; ctx.fill();
      if (p.life > p.max) puffs.splice(i,1);
    }
    ctx.globalAlpha = 1;
    requestAnimationFrame(draw);
  }
  requestAnimationFrame(draw);
})();
</script>
</div>''',
