  PresentationComponentDefinition(
    kind: PresentationComponentKind.teknoloji10,
    id: "teknoloji-bilgisayar-10-buyuk-veri-gorsellestirmesi",
    label: "Büyük Veri Görselleştirmesi",
    category: "Teknoloji / Bilgisayar",
    tags: <String>["büyük veri", "veri", "veri tabanı", "işlemci", "teknoloji"],
    description:
        "Sürekli yükselip alçalan çubuklarıyla canlı veri akışını temsil eden bir büyük veri (big data) grafiği. (Teknik: Canvas + `requestAnimationFrame`)",
    html: r'''<div class="sutol-tek-10-buyukveri">
  <canvas class="sutol-tek-10-canvas"></canvas>
</div>
<style>
.sutol-tek-10-buyukveri{width:100%;height:100%;position:relative;}
.sutol-tek-10-canvas{width:100%;height:100%;display:block;}
</style>
<script>
(function(){
  var root = document.currentScript.previousElementSibling;
  var canvas = root.querySelector('.sutol-tek-10-canvas');
  var ctx = canvas.getContext('2d');
  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function resize(){
    var rect = root.getBoundingClientRect();
    canvas.width = Math.max(rect.width,1) * (window.devicePixelRatio || 1);
    canvas.height = Math.max(rect.height,1) * (window.devicePixelRatio || 1);
  }
  resize();
  window.addEventListener('resize', resize);

  var bars = 7;
  var phase = new Array(bars).fill(0).map(function(_,i){ return i * 0.9; });
  var colors = ['#5b8ad6','#7fd6a0','#d6c25b','#d68a5b','#8a5bd6','#5bd6c2','#d65b8a'];
  var t = 0;
  var speed = reduceMotion ? 0.006 : 0.03;

  function draw(){
    var w = canvas.width, h = canvas.height;
    ctx.clearRect(0,0,w,h);
    var gap = w * 0.02;
    var barW = (w - gap*(bars+1)) / bars;
    for(var i=0;i<bars;i++){
      var val = (Math.sin(t + phase[i]) + 1) / 2;
      var barH = h * (0.15 + val * 0.65);
      var x = gap + i*(barW+gap);
      var y = h - barH;
      ctx.fillStyle = colors[i % colors.length];
      var r = barW*0.15;
      ctx.beginPath();
      ctx.moveTo(x, y+r);
      ctx.arcTo(x,y,x+r,y,r);
      ctx.lineTo(x+barW-r,y);
      ctx.arcTo(x+barW,y,x+barW,y+r,r);
      ctx.lineTo(x+barW,h);
      ctx.lineTo(x,h);
      ctx.closePath();
      ctx.fill();
    }
    t += speed;
    requestAnimationFrame(draw);
  }
  requestAnimationFrame(draw);
})();
</script>''',
  ),
  PresentationComponentDefinition(
    kind: PresentationComponentKind.teknoloji11,
    id: "teknoloji-bilgisayar-11-ag-baglant-haritas",
    label: "Ağ Bağlantı Haritası",
    category: "Teknoloji / Bilgisayar",
    tags: <String>[
      "ağ",
      "internet",
      "sunucu",
      "telekomünikasyon",
      "ağ güvenliği"
    ],
    description:
        "Düğümler arasında sürekli veri paketlerinin dolaştığı canlı bir bilgisayar ağı haritası. (Teknik: Canvas + `requestAnimationFrame`)",
    html: r'''<div class="sutol-tek-11-ag">
  <canvas class="sutol-tek-11-canvas"></canvas>
</div>
<style>
.sutol-tek-11-ag{width:100%;height:100%;position:relative;}
.sutol-tek-11-canvas{width:100%;height:100%;display:block;}
</style>
<script>
(function(){
  var root = document.currentScript.previousElementSibling;
  var canvas = root.querySelector('.sutol-tek-11-canvas');
  var ctx = canvas.getContext('2d');
  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function resize(){
    var rect = root.getBoundingClientRect();
    canvas.width = Math.max(rect.width,1) * (window.devicePixelRatio || 1);
    canvas.height = Math.max(rect.height,1) * (window.devicePixelRatio || 1);
  }
  resize();
  window.addEventListener('resize', resize);

  var nodes = [
    {x:0.5,y:0.15},{x:0.2,y:0.45},{x:0.8,y:0.45},
    {x:0.35,y:0.8},{x:0.65,y:0.8},{x:0.5,y:0.5}
  ];
  var edges = [[0,5],[1,5],[2,5],[3,5],[4,5],[1,3],[2,4]];
  var t = 0;
  var speed = reduceMotion ? 0.0015 : 0.006;

  function draw(){
    var w = canvas.width, h = canvas.height;
    ctx.clearRect(0,0,w,h);
    ctx.strokeStyle = 'rgba(120,150,214,0.4)';
    ctx.lineWidth = w*0.004;
    edges.forEach(function(e){
      var a = nodes[e[0]], b = nodes[e[1]];
      ctx.beginPath();
      ctx.moveTo(a.x*w,a.y*h);
      ctx.lineTo(b.x*w,b.y*h);
      ctx.stroke();
    });
    nodes.forEach(function(n,i){
      ctx.fillStyle = i===5 ? '#d65b8a' : '#5b8ad6';
      ctx.beginPath();
      ctx.arc(n.x*w,n.y*h, i===5 ? w*0.03 : w*0.022,0,Math.PI*2);
      ctx.fill();
    });
    edges.forEach(function(e,idx){
      var a = nodes[e[0]], b = nodes[e[1]];
      var frac = (t + idx*0.18) % 1;
      var x = a.x + (b.x-a.x)*frac, y = a.y + (b.y-a.y)*frac;
      ctx.fillStyle = '#7fd6a0';
      ctx.beginPath();
      ctx.arc(x*w,y*h,w*0.012,0,Math.PI*2);
      ctx.fill();
    });
    t += speed;
    requestAnimationFrame(draw);
  }
  requestAnimationFrame(draw);
})();
</script>''',
