  PresentationComponentDefinition(
    kind: PresentationComponentKind.teknoloji20,
    id: "teknoloji-bilgisayar-20-sifreli-veri-ak-s",
    label: "Şifreli Veri Akışı",
    category: "Teknoloji / Bilgisayar",
    tags: <String>["şifreleme", "siber güvenlik", "kripto para", "veri", "kod"],
    description:
        "Ortasında kilitli bir simge bulunurken arka planda ikili (binary) rakamların yukarıdan aşağı süzülerek şifrelenmiş veri akışını simgelediği bir kompozisyon. (Teknik: Canvas + `requestAnimationFrame`)",
    html: r'''<div class="sutol-tek-20-sifreleme">
  <canvas class="sutol-tek-20-canvas"></canvas>
  <svg class="sutol-tek-20-lock" viewBox="0 0 100 100" preserveAspectRatio="xMidYMid meet" xmlns="http://www.w3.org/2000/svg">
    <rect x="30" y="48" width="40" height="32" rx="5" fill="#1a2030" stroke="#7fd6a0" stroke-width="3"/>
    <path d="M36,48 L36,36 C36,22 64,22 64,36 L64,48" fill="none" stroke="#7fd6a0" stroke-width="5"/>
    <circle cx="50" cy="62" r="4" fill="#7fd6a0"/>
  </svg>
</div>
<style>
.sutol-tek-20-sifreleme{width:100%;height:100%;position:relative;display:flex;align-items:center;justify-content:center;}
.sutol-tek-20-canvas{width:100%;height:100%;display:block;position:absolute;inset:0;}
.sutol-tek-20-lock{width:40%;height:40%;position:relative;filter:drop-shadow(0 0 6px rgba(127,214,160,0.5));}
</style>
<script>
(function(){
  var root = document.currentScript.previousElementSibling;
  var canvas = root.querySelector('.sutol-tek-20-canvas');
  var ctx = canvas.getContext('2d');
  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function resize(){
    var rect = root.getBoundingClientRect();
    canvas.width = Math.max(rect.width,1) * (window.devicePixelRatio || 1);
    canvas.height = Math.max(rect.height,1) * (window.devicePixelRatio || 1);
    columns = Math.max(Math.floor(canvas.width / (canvas.width*0.045)),8);
    drops = new Array(columns).fill(0).map(function(){ return Math.random(); });
  }
  var columns = 10, drops = [];
  resize();
  window.addEventListener('resize', resize);

  var speed = reduceMotion ? 0.0015 : 0.01;

  function draw(){
    var w = canvas.width, h = canvas.height;
    ctx.clearRect(0,0,w,h);
    var colW = w / columns;
    ctx.font = Math.max(colW*0.85,8) + 'px monospace';
    ctx.fillStyle = 'rgba(127,214,160,0.55)';
    ctx.textAlign = 'center';
    for(var i=0;i<columns;i++){
      var y = ((drops[i] + 'x').length ? drops[i] : 0);
      var frac = (drops[i] + speed*i*0.02) % 1;
      drops[i] = frac;
      var yPos = frac * (h*1.2) - h*0.1;
      var digit = Math.round((frac*997) % 2);
      ctx.fillText(String(digit), colW*i + colW/2, yPos);
    }
    for(var j=0;j<columns;j++){
      drops[j] = (drops[j] + speed) % 1;
    }
    requestAnimationFrame(draw);
  }
  requestAnimationFrame(draw);
})();
</script>''',
  ),
