  PresentationComponentDefinition(
    kind: PresentationComponentKind.astronomi09,
    id: "astronomi-09-meteor-yagmuru",
    label: "Meteor Yağmuru",
    category: "Astronomi",
    tags: <String>["meteor yağmuru", "meteor", "göktaşı"],
    description: "Astronomi kategorisi için animasyonlu HTML bileşeni.",
    html: r'''<div id="sutol-ast-09" class="sutol-ast-09-root">
<style>
.sutol-ast-09-root{width:100%;height:100%;background:transparent;}
.sutol-ast-09-canvas{width:100%;height:100%;display:block;}
</style>
<canvas class="sutol-ast-09-canvas"></canvas>
<script>
(function(){
  var root = document.getElementById('sutol-ast-09');
  var canvas = root.querySelector('.sutol-ast-09-canvas');
  var ctx = canvas.getContext('2d');
  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var meteors = [];
  function resize(){
    var r = root.getBoundingClientRect();
    canvas.width = Math.max(1, r.width);
    canvas.height = Math.max(1, r.height);
  }
  if (window.ResizeObserver){ new ResizeObserver(resize).observe(root); }
  resize();
  function spawn(){
    meteors.push({
      x: Math.random() * canvas.width,
      y: -10,
      len: 30 + Math.random() * 40,
      speed: reduce ? 1.2 : (3 + Math.random() * 4),
      angle: Math.PI/4 + (Math.random()*0.15 - 0.075)
    });
  }
  var spawnTimer = 0;
  function draw(){
    ctx.clearRect(0,0,canvas.width,canvas.height);
    spawnTimer++;
    if (spawnTimer > (reduce ? 90 : 26)){ spawn(); spawnTimer = 0; }
    for (var i = meteors.length - 1; i >= 0; i--){
      var m = meteors[i];
      var dx = Math.cos(m.angle) * m.speed;
      var dy = Math.sin(m.angle) * m.speed;
      m.x += dx; m.y += dy;
      var tailX = m.x - Math.cos(m.angle) * m.len;
      var tailY = m.y - Math.sin(m.angle) * m.len;
      var grad = ctx.createLinearGradient(m.x, m.y, tailX, tailY);
      grad.addColorStop(0, 'rgba(255,255,255,0.95)');
      grad.addColorStop(1, 'rgba(255,255,255,0)');
      ctx.strokeStyle = grad;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(m.x, m.y);
      ctx.lineTo(tailX, tailY);
      ctx.stroke();
      if (m.y > canvas.height + 20 || m.x > canvas.width + 20) meteors.splice(i,1);
    }
    requestAnimationFrame(draw);
  }
  requestAnimationFrame(draw);
})();
</script>
</div>''',
  ),
