  PresentationComponentDefinition(
    kind: PresentationComponentKind.astronomi16,
    id: "astronomi-16-big-bang-evrenin-dogusu",
    label: "Big Bang / Evrenin Doğuşu",
    category: "Astronomi",
    tags: <String>["big bang", "büyük patlama", "evrenin doğuşu"],
    description: "Astronomi kategorisi için animasyonlu HTML bileşeni.",
    html: r'''<div id="sutol-ast-16" class="sutol-ast-16-root">
<style>
.sutol-ast-16-root{width:100%;height:100%;background:transparent;}
.sutol-ast-16-canvas{width:100%;height:100%;display:block;}
</style>
<canvas class="sutol-ast-16-canvas"></canvas>
<script>
(function(){
  var root = document.getElementById('sutol-ast-16');
  var canvas = root.querySelector('.sutol-ast-16-canvas');
  var ctx = canvas.getContext('2d');
  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var particles = [];
  var W, H, cx, cy;
  function resize(){
    var r = root.getBoundingClientRect();
    W = canvas.width = Math.max(1, r.width);
    H = canvas.height = Math.max(1, r.height);
    cx = W/2; cy = H/2;
  }
  if (window.ResizeObserver){ new ResizeObserver(resize).observe(root); }
  resize();
  var colors = ['#ffe9b3','#ffc27a','#9fd8ff','#c9a8ff','#ffffff'];
  function reset(p){
    var angle = Math.random() * Math.PI * 2;
    var speed = (0.4 + Math.random() * 1.6) * (reduce ? 0.35 : 1);
    p.angle = angle; p.speed = speed;
    p.life = 0;
    p.maxLife = 90 + Math.random() * 90;
    p.color = colors[Math.floor(Math.random()*colors.length)];
    p.size = 0.8 + Math.random() * 1.6;
  }
  var count = 90;
  for (var i=0;i<count;i++){ var p = {}; reset(p); p.life = Math.random()*p.maxLife; particles.push(p); }
  function draw(){
    ctx.fillStyle = 'rgba(0,0,0,0)';
    ctx.clearRect(0,0,W,H);
    for (var i=0;i<particles.length;i++){
      var p = particles[i];
      p.life += 1;
      if (p.life > p.maxLife) reset(p);
      var t = p.life / p.maxLife;
      var dist = t * Math.min(W,H) * 0.55;
      var x = cx + Math.cos(p.angle) * dist;
      var y = cy + Math.sin(p.angle) * dist;
      ctx.globalAlpha = 1 - t;
      ctx.beginPath();
      ctx.arc(x, y, p.size, 0, Math.PI*2);
      ctx.fillStyle = p.color;
      ctx.fill();
    }
    ctx.globalAlpha = 1;
    var g = ctx.createRadialGradient(cx,cy,0,cx,cy,30);
    g.addColorStop(0,'rgba(255,255,255,0.9)');
    g.addColorStop(1,'rgba(255,255,255,0)');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(cx,cy,30,0,Math.PI*2); ctx.fill();
    requestAnimationFrame(draw);
  }
  requestAnimationFrame(draw);
})();
</script>
</div>''',
  ),
