    <ellipse cx="55" cy="68" rx="15" ry="7" fill="#ff9f6b" class="sutol-bio-01-mito1"/>
    <ellipse cx="142" cy="128" rx="15" ry="7" fill="#ff9f6b" class="sutol-bio-01-mito2"/>
    <ellipse cx="146" cy="62" rx="12" ry="6" fill="#ffce6b" class="sutol-bio-01-mito3"/>
    <circle cx="65" cy="140" r="7" fill="#c98bff" class="sutol-bio-01-vac"/>
  </svg>
</div>
<style>
.sutol-bio-01-hucre{width:100%;height:100%;display:flex;align-items:center;justify-content:center;}
.sutol-bio-01-hucre svg{width:100%;height:100%;}
.sutol-bio-01-membrane{transform-origin:100px 100px;animation:sutolBio01Breathe 6s ease-in-out infinite;}
.sutol-bio-01-nucleus,.sutol-bio-01-nucleolus{transform-origin:100px 100px;animation:sutolBio01Pulse 4s ease-in-out infinite;}
.sutol-bio-01-mito1{animation:sutolBio01Drift1 8s ease-in-out infinite;}
.sutol-bio-01-mito2{animation:sutolBio01Drift2 9s ease-in-out infinite;}
.sutol-bio-01-mito3{animation:sutolBio01Drift3 7s ease-in-out infinite;}
.sutol-bio-01-vac{animation:sutolBio01Drift2 11s ease-in-out infinite;}
@keyframes sutolBio01Breathe{0%,100%{transform:scale(1);}50%{transform:scale(1.02);}}
@keyframes sutolBio01Pulse{0%,100%{transform:scale(1);}50%{transform:scale(1.09);}}
@keyframes sutolBio01Drift1{0%,100%{transform:translate(0,0);}50%{transform:translate(9px,-6px);}}
@keyframes sutolBio01Drift2{0%,100%{transform:translate(0,0);}50%{transform:translate(-9px,7px);}}
@keyframes sutolBio01Drift3{0%,100%{transform:translate(0,0);}50%{transform:translate(-7px,-8px);}}
@media (prefers-reduced-motion: reduce){
  .sutol-bio-01-hucre *{animation-duration:40s !important;}
}
</style>''',
