  PresentationComponentDefinition(
    kind: PresentationComponentKind.biyoloji10,
    id: "biyoloji-10-sinir-sinyali",
    label: "Sinir Sinyali",
    category: "Biyoloji",
    tags: <String>["sinir", "sistem", "hücre", "fizyoloji", "anatomi"],
    description:
        "Dendritlerden aksona doğru ilerleyen bir elektriksel sinir sinyalinin canvas üzerinde çizilen akışı. (Teknik: Canvas + `requestAnimationFrame`)",
    html: r'''<div class="sutol-bio-10-noron">
  <canvas class="sutol-bio-10-canvas"></canvas>
</div>
<style>
.sutol-bio-10-noron{width:100%;height:100%;position:relative;}
.sutol-bio-10-canvas{width:100%;height:100%;display:block;}
</style>
<script>
(function(){
  var root = document.currentScript.previousElementSibling;
  var canvas = root.querySelector('.sutol-bio-10-canvas');
  var ctx = canvas.getContext('2d');
  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function resize(){
    var rect = root.getBoundingClientRect();
    canvas.width = Math.max(rect.width, 1) * (window.devicePixelRatio || 1);
    canvas.height = Math.max(rect.height, 1) * (window.devicePixelRatio || 1);
  }
  resize();
  window.addEventListener('resize', resize);

  var path = [
    [0.08,0.30],[0.08,0.55],[0.20,0.55],[0.20,0.30],
    [0.20,0.55],[0.55,0.55],[0.85,0.55],
    [0.85,0.30],[0.85,0.80]
  ];
  var t = 0;
  var speed = reduceMotion ? 0.0015 : 0.006;

  function pointAt(frac){
    var segCount = path.length - 1;
    var pos = frac * segCount;
    var i = Math.min(Math.floor(pos), segCount - 1);
    var localT = pos - i;
    var a = path[i], b = path[i+1];
    return [a[0] + (b[0]-a[0]) * localT, a[1] + (b[1]-a[1]) * localT];
  }

  function draw(){
    var w = canvas.width, h = canvas.height;
    ctx.clearRect(0,0,w,h);
    ctx.strokeStyle = '#9fb6ff';
    ctx.lineWidth = w * 0.012;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.beginPath();
    path.forEach(function(p,i){
      var x = p[0]*w, y = p[1]*h;
      if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
    });
    ctx.stroke();

    for(var k=0;k<3;k++){
      var frac = (t + k*0.33) % 1;
      var pos = pointAt(frac);
      var grad = ctx.createRadialGradient(pos[0]*w,pos[1]*h,0,pos[0]*w,pos[1]*h,w*0.035);
      grad.addColorStop(0,'rgba(255,214,102,0.95)');
      grad.addColorStop(1,'rgba(255,214,102,0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(pos[0]*w,pos[1]*h,w*0.035,0,Math.PI*2);
      ctx.fill();
    }
    t += speed;
    requestAnimationFrame(draw);
  }
  requestAnimationFrame(draw);
})();
</script>''',
