  PresentationComponentDefinition(
    kind: PresentationComponentKind.biyoloji18,
    id: "biyoloji-18-besin-zinciri-dongusu",
    label: "Besin Zinciri Döngüsü",
    category: "Biyoloji",
    tags: <String>["besin zinciri", "ekosistem", "ekoloji", "canlı", "habitat"],
    description:
        "Güneşten bitkiye, otçuldan etçile enerji akışını dairesel bir yol üzerinde akan parçacıklarla gösteren bir besin zinciri şeması. (Teknik: Canvas + `requestAnimationFrame`)",
    html: r'''<div class="sutol-bio-18-besinzinciri">
  <canvas class="sutol-bio-18-canvas"></canvas>
</div>
<style>
.sutol-bio-18-besinzinciri{width:100%;height:100%;position:relative;}
.sutol-bio-18-canvas{width:100%;height:100%;display:block;}
</style>
<script>
(function(){
  var root = document.currentScript.previousElementSibling;
  var canvas = root.querySelector('.sutol-bio-18-canvas');
  var ctx = canvas.getContext('2d');
  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function resize(){
    var rect = root.getBoundingClientRect();
    canvas.width = Math.max(rect.width,1) * (window.devicePixelRatio || 1);
    canvas.height = Math.max(rect.height,1) * (window.devicePixelRatio || 1);
  }
  resize();
  window.addEventListener('resize', resize);

  var nodes = [
    {frac:0.0, color:'#ffd24a', shape:'sun'},
    {frac:0.25, color:'#6bbf6a', shape:'plant'},
    {frac:0.5, color:'#e0a05b', shape:'herb'},
    {frac:0.75, color:'#d65b5b', shape:'carn'}
  ];
  var t = 0;
  var speed = reduceMotion ? 0.0012 : 0.004;

  function nodePos(frac,w,h){
    var cx = w*0.5, cy = h*0.5, r = Math.min(w,h)*0.34;
    var angle = frac * Math.PI*2 - Math.PI/2;
    return [cx + Math.cos(angle)*r, cy + Math.sin(angle)*r];
  }

  function drawShape(shape,x,y,size,color){
    ctx.fillStyle = color;
    if(shape==='sun'){
      ctx.beginPath(); ctx.arc(x,y,size,0,Math.PI*2); ctx.fill();
    } else if(shape==='plant'){
      ctx.beginPath(); ctx.moveTo(x,y-size); ctx.lineTo(x+size,y+size); ctx.lineTo(x-size,y+size); ctx.closePath(); ctx.fill();
    } else if(shape==='herb'){
      ctx.beginPath(); ctx.rect(x-size,y-size,size*2,size*2); ctx.fill();
    } else {
      ctx.beginPath();
      ctx.moveTo(x,y-size); ctx.lineTo(x+size,y); ctx.lineTo(x,y+size); ctx.lineTo(x-size,y); ctx.closePath(); ctx.fill();
    }
  }

  function draw(){
    var w = canvas.width, h = canvas.height;
    ctx.clearRect(0,0,w,h);
    var cx=w*0.5, cy=h*0.5, r=Math.min(w,h)*0.34;
    ctx.strokeStyle = 'rgba(150,180,150,0.4)';
    ctx.lineWidth = w*0.008;
    ctx.beginPath();
    ctx.arc(cx,cy,r,0,Math.PI*2);
    ctx.stroke();

    nodes.forEach(function(n){
      var p = nodePos(n.frac,w,h);
      drawShape(n.shape,p[0],p[1],w*0.045,n.color);
    });

    for(var k=0;k<3;k++){
      var frac = (t + k*0.33) % 1;
      var p = nodePos(frac,w,h);
      ctx.fillStyle = 'rgba(255,255,255,0.9)';
      ctx.beginPath();
      ctx.arc(p[0],p[1],w*0.015,0,Math.PI*2);
      ctx.fill();
    }
    t += speed;
    requestAnimationFrame(draw);
  }
  requestAnimationFrame(draw);
})();
</script>''',
  ),
