  PresentationComponentDefinition(
    kind: PresentationComponentKind.fizik05,
    id: "fizik-05-is-ve-termodinamik",
    label: "Isı ve Termodinamik",
    category: "Fizik",
    tags: <String>["sıcaklık", "ısı", "termodinamik", "entropi", "plazma"],
    description:
        "Bir kutu içindeki parçacıkların ısınma-soğuma döngüsüne bağlı olarak hızlanıp yavaşladığı bir moleküler hareket simülasyonu.",
    html: r'''<div class="sutol-fizik-05-wrap">
<style>
.sutol-fizik-05-wrap{width:100%;height:100%;background:transparent;position:relative;}
.sutol-fizik-05-canvas{width:100%;height:100%;display:block;}
</style>
<canvas class="sutol-fizik-05-canvas"></canvas>
<script>
(function(){
  var root = document.currentScript.parentElement;
  var canvas = root.querySelector('.sutol-fizik-05-canvas');
  var ctx = canvas.getContext('2d');
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var W,H,dpr;
  function resize(){
    dpr = window.devicePixelRatio||1;
    W = canvas.clientWidth; H = canvas.clientHeight;
    canvas.width = W*dpr; canvas.height = H*dpr;
    ctx.setTransform(dpr,0,0,dpr,0,0);
  }
  window.addEventListener('resize', resize);
  resize();

  var N = 10;
  var particles = [];
  for(var i=0;i<N;i++){
    particles.push({ x: Math.random(), y: Math.random(), vx:(Math.random()-0.5), vy:(Math.random()-0.5) });
  }

  var start = null;
  function lerpColor(a,b,t){ return [a[0]+(b[0]-a[0])*t, a[1]+(b[1]-a[1])*t, a[2]+(b[2]-a[2])*t]; }
  var cold=[95,170,224], hot=[224,95,86];

  function frame(ts){
    if(!start) start=ts;
    var t = (ts-start)/1000;
    var cycle = (Math.sin(t*(reduced?0.15:0.5))+1)/2;
    var speedMul = reduced ? 0.15 : (0.4 + cycle*1.6);
    ctx.clearRect(0,0,W,H);

    var pad = Math.min(W,H)*0.08;
    var boxX = pad, boxY = pad, boxW = W-pad*2, boxH = H-pad*2;
    ctx.strokeStyle = 'rgba(120,130,150,0.35)';
    ctx.lineWidth = 2;
    ctx.strokeRect(boxX, boxY, boxW, boxH);

    var col = lerpColor(cold, hot, cycle);
    var colStr = 'rgb('+Math.round(col[0])+','+Math.round(col[1])+','+Math.round(col[2])+')';

    for(var i=0;i<particles.length;i++){
      var p = particles[i];
      p.x += p.vx*speedMul*0.003;
      p.y += p.vy*speedMul*0.003;
      if(p.x<0||p.x>1) p.vx*=-1;
      if(p.y<0||p.y>1) p.vy*=-1;
      p.x = Math.max(0,Math.min(1,p.x));
      p.y = Math.max(0,Math.min(1,p.y));
      var px = boxX + p.x*boxW;
      var py = boxY + p.y*boxH;
      ctx.beginPath();
      ctx.arc(px,py, Math.min(W,H)*0.018, 0, Math.PI*2);
      ctx.fillStyle = colStr;
      ctx.fill();
    }
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
</script>
</div>''',
