  PresentationComponentDefinition(
    kind: PresentationComponentKind.fizik07,
    id: "fizik-07-dalga-girisimi",
    label: "Dalga Girişimi",
    category: "Fizik",
    tags: <String>["dalga", "girişim", "frekans", "genlik", "süperpozisyon"],
    description:
        "İki nokta kaynaktan yayılan dairesel dalgaların üst üste binerek oluşturduğu girişim desenini gösterir.",
    html: r'''<div class="sutol-fizik-07-wrap">
<style>
.sutol-fizik-07-wrap{width:100%;height:100%;background:transparent;position:relative;}
.sutol-fizik-07-canvas{width:100%;height:100%;display:block;}
</style>
<canvas class="sutol-fizik-07-canvas"></canvas>
<script>
(function(){
  var root = document.currentScript.parentElement;
  var canvas = root.querySelector('.sutol-fizik-07-canvas');
  var ctx = canvas.getContext('2d');
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var W,H,dpr;
  function resize(){
    dpr = window.devicePixelRatio||1;
    W = canvas.clientWidth; H = canvas.clientHeight;
    canvas.width = W*dpr; canvas.height = H*dpr;
    ctx.setTransform(dpr,0,0,dpr,0,0);
  }
  window.addEventListener('resize', resize);
  resize();
  var start=null;
  function frame(ts){
    if(!start) start=ts;
    var t=(ts-start)/1000*(reduced?0.25:1);
    ctx.clearRect(0,0,W,H);
    var sources=[{x:W*0.38,y:H*0.5},{x:W*0.62,y:H*0.5}];
    var maxR = Math.max(W,H)*0.9;
    var spacing = Math.min(W,H)*0.055;
    ctx.lineWidth=1.2;
    for(var s=0;s<sources.length;s++){
      var src=sources[s];
      for(var r=(t*40)%spacing; r<maxR; r+=spacing){
        var alpha = Math.max(0,0.5-(r/maxR)*0.5);
        ctx.beginPath();
        ctx.arc(src.x,src.y,r,0,Math.PI*2);
        ctx.strokeStyle='rgba(95,208,224,'+alpha.toFixed(3)+')';
        ctx.stroke();
      }
    }
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
</script>
</div>''',
