.sutol-mat-20-radius{stroke:#3d4b66;stroke-width:2.5;}
.sutol-mat-20-cos{stroke:#e0a24d;stroke-width:3;}
.sutol-mat-20-sin{stroke:#5a9bd8;stroke-width:3;}
.sutol-mat-20-pt{fill:#5aa87a;}
</style>
<svg viewBox="0 0 300 300">
  <circle class="sutol-mat-20-circle" cx="150" cy="150" r="90"/>
  <line class="sutol-mat-20-axis" x1="40" y1="150" x2="260" y2="150"/>
  <line class="sutol-mat-20-axis" x1="150" y1="40" x2="150" y2="260"/>
  <line class="sutol-mat-20-cos" data-role="cos" x1="150" y1="150" x2="150" y2="150"/>
  <line class="sutol-mat-20-sin" data-role="sin" x1="150" y1="150" x2="150" y2="150"/>
  <line class="sutol-mat-20-radius" data-role="radius" x1="150" y1="150" x2="240" y2="150"/>
  <circle class="sutol-mat-20-pt" data-role="point" cx="240" cy="150" r="5"/>
</svg>
<script>
(function(){
  var root = document.currentScript.parentElement;
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var radius = root.querySelector('[data-role="radius"]');
  var cos = root.querySelector('[data-role="cos"]');
  var sin = root.querySelector('[data-role="sin"]');
  var pt = root.querySelector('[data-role="point"]');
  var cx=150, cy=150, r=90;
  var start=null;
  var speed = reduced ? 0.15 : 0.6;
  function frame(ts){
    if(!start) start=ts;
    var t=(ts-start)/1000;
    var a = t*speed;
    var x = cx + r*Math.cos(a);
    var y = cy - r*Math.sin(a);
    radius.setAttribute('x2', x); radius.setAttribute('y2', y);
    pt.setAttribute('cx', x); pt.setAttribute('cy', y);
    cos.setAttribute('x1', cx); cos.setAttribute('y1', cy);
    cos.setAttribute('x2', x); cos.setAttribute('y2', cy);
    sin.setAttribute('x1', x); sin.setAttribute('y1', cy);
    sin.setAttribute('x2', x); sin.setAttribute('y2', y);
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
</script>
</div>''',
