  PresentationComponentDefinition(
    kind: PresentationComponentKind.kimya10,
    id: "kimya-10-gaz-kinetik-teorisi",
    label: "Gaz Kinetik Teorisi",
    category: "Kimya",
    tags: <String>["gaz", "kinetik teori", "basınç", "sıcaklık", "molekül"],
    description:
        "Kapalı bir kap içindeki gaz moleküllerinin rastgele hareket ederek duvarlara çarptığı kinetik teori modelini gösterir.",
    html: r'''<div class="sutol-kimya-10-wrap">
<style>
.sutol-kimya-10-wrap{width:100%;height:100%;background:transparent;position:relative;}
.sutol-kimya-10-canvas{width:100%;height:100%;display:block;}
</style>
<canvas class="sutol-kimya-10-canvas"></canvas>
<script>
(function(){
  var root = document.currentScript.parentElement;
  var canvas = root.querySelector('.sutol-kimya-10-canvas');
  var ctx = canvas.getContext('2d');
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var W,H,dpr;
  function resize(){
    dpr = window.devicePixelRatio||1;
    W = canvas.clientWidth; H = canvas.clientHeight;
    canvas.width = W*dpr; canvas.height = H*dpr;
    ctx.setTransform(dpr,0,0,dpr,0,0);
  }
  window.addEventListener('resize', resize);
  resize();
  var N=14;
  var particles=[];
  for(var i=0;i<N;i++){
    particles.push({x:Math.random(),y:Math.random(),vx:(Math.random()-0.5)*0.006,vy:(Math.random()-0.5)*0.006});
  }
  function frame(){
    var speedMul = reduced?0.25:1;
    var pad = Math.min(W,H)*0.1;
    var boxX=pad,boxY=pad,boxW=W-pad*2,boxH=H-pad*2;
    ctx.clearRect(0,0,W,H);
    ctx.strokeStyle='rgba(127,227,232,0.4)';
    ctx.lineWidth=2;
    ctx.strokeRect(boxX,boxY,boxW,boxH);
    for(var i=0;i<particles.length;i++){
      var p=particles[i];
      p.x+=p.vx*speedMul;
      p.y+=p.vy*speedMul;
      if(p.x<0||p.x>1) p.vx*=-1;
      if(p.y<0||p.y>1) p.vy*=-1;
      p.x=Math.max(0,Math.min(1,p.x));
      p.y=Math.max(0,Math.min(1,p.y));
      var px=boxX+p.x*boxW, py=boxY+p.y*boxH;
      ctx.beginPath();
      ctx.arc(px,py,Math.min(W,H)*0.014,0,Math.PI*2);
      ctx.fillStyle='rgba(111,207,151,0.9)';
      ctx.fill();
    }
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
</script>
</div>''',
  ),
  PresentationComponentDefinition(
