  PresentationComponentDefinition(
    kind: PresentationComponentKind.kimya18,
    id: "kimya-18-maddenin-halleri",
    label: "Maddenin Halleri",
    category: "Kimya",
    tags: <String>["madde", "faz geçişi", "katı", "sıvı", "gaz"],
    description:
        "Parçacıkların düzenli bir katı örgüden titreşen bir sıvıya ve dağılan bir gaza dönüştüğü faz geçişini gösterir.",
    html: r'''<div class="sutol-kimya-18-wrap">
<style>
.sutol-kimya-18-wrap{width:100%;height:100%;background:transparent;position:relative;}
.sutol-kimya-18-canvas{width:100%;height:100%;display:block;}
</style>
<canvas class="sutol-kimya-18-canvas"></canvas>
<script>
(function(){
  var root = document.currentScript.parentElement;
  var canvas = root.querySelector('.sutol-kimya-18-canvas');
  var ctx = canvas.getContext('2d');
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var W,H,dpr;
  function resize(){
    dpr = window.devicePixelRatio||1;
    W = canvas.clientWidth; H = canvas.clientHeight;
    canvas.width = W*dpr; canvas.height = H*dpr;
    ctx.setTransform(dpr,0,0,dpr,0,0);
  }
  window.addEventListener('resize', resize);
  resize();
  var cols=4, rows=3;
  var particles=[];
  for(var r=0;r<rows;r++){
    for(var c=0;c<cols;c++){
      particles.push({gx:(c+1)/(cols+1), gy:(r+1)/(rows+1), phase:Math.random()*Math.PI*2, fx:Math.random()-0.5, fy:Math.random()-0.5});
    }
  }
  var start=null;
  function frame(ts){
    if(!start) start=ts;
    var t=(ts-start)/1000*(reduced?0.2:1);
    var cyclePos = (t%9)/9;
    var stage = cyclePos<0.34?0:(cyclePos<0.67?1:2);
    var localT = t*2;
    ctx.clearRect(0,0,W,H);
    for(var i=0;i<particles.length;i++){
      var p=particles[i];
      var baseX = p.gx*W, baseY = p.gy*H;
      var x,y;
      if(stage===0){
        x = baseX + Math.sin(localT+p.phase)*1.5;
        y = baseY + Math.cos(localT+p.phase)*1.5;
      } else if(stage===1){
        x = baseX + Math.sin(localT*1.6+p.phase)*8;
        y = baseY + Math.cos(localT*1.6+p.phase*1.3)*8;
      } else {
        x = baseX + p.fx*W*0.35*Math.sin(localT*0.4+p.phase);
        y = baseY + p.fy*H*0.35*Math.cos(localT*0.4+p.phase);
      }
      ctx.beginPath();
      ctx.arc(x,y,Math.min(W,H)*0.02,0,Math.PI*2);
      ctx.fillStyle='rgba(127,227,232,0.85)';
      ctx.fill();
    }
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
</script>
</div>''',
  ),
