  PresentationComponentDefinition(
    kind: PresentationComponentKind.sehirKentsel16,
    id: "sehir-yasam-kentsel-altyap-16-ak-ll-ulas-m-ag",
    label: "Akıllı Ulaşım Ağı",
    category: "Şehir Yaşamı & Kentsel Altyapı",
    tags: <String>[
      "toplu taşıma",
      "akıllı şehir",
      "altyapı ağı",
      "metro istasyonu"
    ],
    description:
        "Otobüs, tramvay ve metro hatlarının aynı anda izlendiği canlı bir şehir içi ulaşım ağı haritası. (Teknik: Canvas + `requestAnimationFrame`)",
    html: r'''<div class="sutol-kent-16-ulasimagi">
  <canvas class="sutol-kent-16-canvas"></canvas>
</div>
<style>
.sutol-kent-16-ulasimagi{width:100%;height:100%;position:relative;}
.sutol-kent-16-canvas{width:100%;height:100%;display:block;}
</style>
<script>
(function(){
  var root = document.currentScript.previousElementSibling;
  var canvas = root.querySelector('.sutol-kent-16-canvas');
  var ctx = canvas.getContext('2d');
  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function resize(){
    var rect = root.getBoundingClientRect();
    canvas.width = Math.max(rect.width,1) * (window.devicePixelRatio || 1);
    canvas.height = Math.max(rect.height,1) * (window.devicePixelRatio || 1);
  }
  resize();
  window.addEventListener('resize', resize);

  var lines = [
    {y:0.25, color:'#5b8ad6'},
    {y:0.5, color:'#5bd68a'},
    {y:0.75, color:'#e0a05b'}
  ];
  var t = 0;
  var speed = reduceMotion ? 0.0015 : 0.006;

  function draw(){
    var w = canvas.width, h = canvas.height;
    ctx.clearRect(0,0,w,h);

    lines.forEach(function(l,i){
      ctx.strokeStyle = 'rgba(150,150,160,0.3)';
      ctx.lineWidth = w*0.008;
      ctx.beginPath();
      ctx.moveTo(w*0.05,l.y*h);
      ctx.lineTo(w*0.95,l.y*h);
      ctx.stroke();

      for(var s=0;s<4;s++){
        ctx.fillStyle = '#8a8a94';
        ctx.beginPath();
        ctx.arc(w*(0.05 + s*0.3), l.y*h, w*0.012, 0, Math.PI*2);
        ctx.fill();
      }

      var frac = (t + i*0.3) % 1;
      var x = w*0.05 + frac*w*0.9;
      ctx.fillStyle = l.color;
      ctx.beginPath();
      ctx.arc(x, l.y*h, w*0.02, 0, Math.PI*2);
      ctx.fill();
    });

    t += speed;
    requestAnimationFrame(draw);
  }
  requestAnimationFrame(draw);
})();
</script>''',
  ),
