      85%,100% { transform: skewY(0deg) scaleX(1); }
    }
    @keyframes sutol-tar-03-fade {
      0%, 15% { opacity: 0; transform: scale(.4); }
      50% { opacity: .9; transform: scale(1); }
      85%,100% { opacity: 0; transform: scale(.4); }
