  PresentationComponentDefinition(
    kind: PresentationComponentKind.matematik28,
    id: "matematik-28-diferansiyel-denklem-egim-alan",
    label: "Diferansiyel Denklem Eğim Alanı",
    category: "Matematik",
    tags: <String>["diferansiyel denklem", "gradyan", "geometrik dönüşüm"],
    description:
        "Bir diferansiyel denklemin çözüm eğrilerini ima eden, hafifçe nefes alan bir eğim (vektör) alanı; tuval (canvas) tabanlı üretim.",
    html: r'''<div class="sutol-mat-08-root" style="width:100%;height:100%;">
  <canvas class="sutol-mat-08-canvas" style="width:100%;height:100%;display:block;background:transparent;"></canvas>
</div>
<style>
  @media (prefers-reduced-motion: reduce){
    .sutol-mat-08-canvas{ animation:none; }
  }
</style>
<script>
(function(){
  var canvas = document.querySelector('.sutol-mat-08-canvas');
  if(!canvas) return;
  var ctx = canvas.getContext('2d');
  var reduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var t = 0;
  function resize(){
    var rect = canvas.getBoundingClientRect();
    canvas.width = rect.width || 200;
    canvas.height = rect.height || 200;
  }
  resize();
  window.addEventListener('resize', resize);
  function slope(x,y){
    return Math.sin(x*0.06) * Math.cos(y*0.06);
  }
  function draw(){
    var w = canvas.width, h = canvas.height;
    ctx.clearRect(0,0,w,h);
    var cols = 12, rows = 12;
    for(var i=0;i<cols;i++){
      for(var j=0;j<rows;j++){
        var x = (i+0.5)*(w/cols);
        var y = (j+0.5)*(h/rows);
        var m = slope(x, y + (reduced?0:Math.sin(t)*4));
        var len = Math.min(w/cols,h/rows)*0.4;
        var ang = Math.atan(m);
        var dx = Math.cos(ang)*len/2;
        var dy = Math.sin(ang)*len/2;
        var hue = 190 + m*40;
        ctx.strokeStyle = 'hsla('+hue+',65%,55%,0.75)';
        ctx.lineWidth = 1.4;
        ctx.beginPath();
        ctx.moveTo(x-dx,y-dy);
        ctx.lineTo(x+dx,y+dy);
        ctx.stroke();
        ctx.fillStyle = ctx.strokeStyle;
        ctx.beginPath();
        ctx.arc(x+dx,y+dy,1.4,0,Math.PI*2);
        ctx.fill();
      }
    }
    if(!reduced){
      t += 0.02;
      requestAnimationFrame(draw);
    }
  }
  draw();
})();
</script>''',
