  PresentationComponentDefinition(
    kind: PresentationComponentKind.matematik35,
    id: "matematik-35-gradyan-t-rman-s",
    label: "Gradyan Tırmanışı",
    category: "Matematik",
    tags: <String>["gradyan", "diferansiyel denklem"],
    description:
        "İç içe eş-potansiyel halkalardan oluşan bir skaler alan üzerinde, en dik çıkış (gradyan) yönünü izleyerek merkeze doğru ilerleyen bir işaretçi; tuval tabanlı üretim.",
    html: r'''<div class="sutol-mat-15-root" style="width:100%;height:100%;">
  <canvas class="sutol-mat-15-canvas" style="width:100%;height:100%;display:block;background:transparent;"></canvas>
</div>
<script>
(function(){
  var canvas = document.querySelector('.sutol-mat-15-canvas');
  if(!canvas) return;
  var ctx = canvas.getContext('2d');
  var reduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  function resize(){
    var rect = canvas.getBoundingClientRect();
    canvas.width = rect.width || 200;
    canvas.height = rect.height || 200;
  }
  resize();
  window.addEventListener('resize', resize);
  var angle = 0.6, radius = 0;
  function draw(){
    var w = canvas.width, h = canvas.height;
    var cx = w/2, cy = h/2;
    var maxR = Math.min(w,h)*0.45;
    ctx.clearRect(0,0,w,h);
    for(var r = maxR; r>0; r -= maxR/7){
      var t = r/maxR;
      ctx.beginPath();
      ctx.arc(cx,cy,r,0,Math.PI*2);
      ctx.strokeStyle = 'hsla('+(20+t*40)+',80%,55%,0.55)';
      ctx.lineWidth = 2;
      ctx.stroke();
    }
    if(!reduced){
      radius += (0 - radius)*0.003 + 0.15;
      angle += 0.06;
    }
    var curR = Math.max(0, maxR - (reduced?maxR*0.4:((performance.now()/60)%(maxR))));
    var px = cx + Math.cos(angle)*curR;
    var py = cy + Math.sin(angle)*curR;
    ctx.beginPath();
    ctx.arc(px,py,4,0,Math.PI*2);
    ctx.fillStyle = '#ffffff';
    ctx.shadowColor = '#ff9f1c';
    ctx.shadowBlur = 10;
    ctx.fill();
    ctx.shadowBlur = 0;
    if(!reduced) requestAnimationFrame(draw);
  }
  draw();
})();
</script>''',
  ),
