final Map<PresentationComponentKind, PresentationComponentDefinition>
    _presentationComponentDefinitionByKind =
    <PresentationComponentKind, PresentationComponentDefinition>{
  for (final definition in presentationComponentDefinitions)
    definition.kind: definition,
};

final Map<String, List<PresentationComponentDefinition>>
    _presentationComponentDefinitionsByCategory = () {
  final index = <String, List<PresentationComponentDefinition>>{};
  for (final definition in presentationComponentDefinitions) {
    index
        .putIfAbsent(
          definition.category,
          () => <PresentationComponentDefinition>[],
        )
        .add(definition);
  }
  return <String, List<PresentationComponentDefinition>>{
    for (final entry in index.entries)
      entry.key: List<PresentationComponentDefinition>.unmodifiable(
        entry.value,
      ),
  };
}();

final List<String> _presentationComponentCategories = List<String>.unmodifiable(
  _presentationComponentDefinitionsByCategory.keys,
);

PresentationComponentDefinition presentationComponentDefinition(
  PresentationComponentKind kind,
) =>
    _presentationComponentDefinitionByKind[kind]!;

String presentationComponentLabel(PresentationComponentKind kind) =>
    presentationComponentDefinition(kind).label;

String presentationComponentSubtitle(PresentationComponentKind kind) {
  final definition = presentationComponentDefinition(kind);
  final tags = definition.tags.take(4).join(', ');
  return tags.isEmpty ? definition.description : tags;
}

String presentationComponentCategory(PresentationComponentKind kind) =>
    presentationComponentDefinition(kind).category;

String presentationComponentHtml(PresentationComponentKind kind) =>
    presentationComponentDefinition(kind).html;

bool presentationComponentHasHtml(PresentationComponentKind kind) =>
    presentationComponentDefinition(kind).html.trim().isNotEmpty;

